WITH metrics AS (SELECT id, store_id, product_id, LAG(quantity, 1) OVER (ORDER BY last_restock, id) AS prev_quantity, NTILE(10) OVER (PARTITION BY store_id ORDER BY quantity DESC, id) AS quantity_bucket, CUME_DIST() OVER (PARTITION BY store_id ORDER BY quantity DESC) AS quantity_cume_dist FROM inventory WHERE quantity BETWEEN 61 AND 156) SELECT s.id, s.product_id, s.prev_quantity, s.quantity_bucket, s.quantity_cume_dist, (SELECT SUM(x.unit_price) FROM order_items x WHERE x.product_id = s.product_id) AS sum_order_item_unit_price FROM metrics s ORDER BY id DESC NULLS LAST LIMIT 10
